/* generated child JS: 01-header/header.corporate-reference/block.js */
// lab-ui block · header.corporate-reference
// Imported from CMS BlockTemplate 5ef64a49-2d1c-44df-873f-8e6f471e4b38 (HEADER).

(function () {
  var RTL_LOCALES = ['ar', 'fa', 'he', 'ur'];

  function normalizeLocale(value) {
    return (value || '').toString().toLowerCase().split('-')[0];
  }

  function getPathLocale() {
    var firstSegment = window.location.pathname.split('/').filter(Boolean)[0];
    var locale = normalizeLocale(firstSegment);
    return /^[a-z]{2}$/.test(locale) ? locale : '';
  }

  function getUrlLocale() {
    return normalizeLocale(new URLSearchParams(window.location.search).get('locale'))
      || getPathLocale();
  }

  function detectBrowserLocale() {
    var browserLangs = navigator.languages && navigator.languages.length
      ? navigator.languages
      : [navigator.language || navigator.userLanguage || 'en'];

    for (var i = 0; i < browserLangs.length; i += 1) {
      var candidate = normalizeLocale(browserLangs[i]);
      if (candidate) {
        return candidate;
      }
    }

    return 'en';
  }

  function getEffectiveLocale() {
    return getUrlLocale()
      || normalizeLocale(document.documentElement.getAttribute('lang'))
      || detectBrowserLocale()
      || 'en';
  }

  function isRTL(locale) {
    return RTL_LOCALES.indexOf(normalizeLocale(locale)) !== -1;
  }

  var locale = getEffectiveLocale();

  window.__swLocale = {
    normalizeLocale: normalizeLocale,
    getPathLocale: getPathLocale,
    getUrlLocale: getUrlLocale,
    detectBrowserLocale: detectBrowserLocale,
    getEffectiveLocale: getEffectiveLocale,
    isRTL: isRTL
  };

  document.documentElement.setAttribute('lang', locale);
  document.documentElement.setAttribute('dir', isRTL(locale) ? 'rtl' : 'ltr');
})();

document.addEventListener('DOMContentLoaded', () => {
  const burgerButton = document.querySelector('.header-burger-button');
  const header = document.querySelector('.header');
  const mobileLinks = document.querySelectorAll('.mobile-menu-link');

  function openMenu() {
    if (!header || !burgerButton) return;
    header.classList.add('is-open');
    burgerButton.classList.add('is-open');
    document.body.style.overflow = 'hidden';
    document.querySelectorAll('.locale-selector.is-open').forEach(el => {
      el.classList.remove('is-open');
      el.querySelector('.locale-trigger')?.setAttribute('aria-expanded', 'false');
    });
  }

  function closeMenu() {
    if (!header || !burgerButton) return;
    header.classList.remove('is-open');
    burgerButton.classList.remove('is-open');
    document.body.style.overflow = '';
  }

  if (burgerButton) {
    burgerButton.addEventListener('click', () => {
      header.classList.contains('is-open') ? closeMenu() : openMenu();
    });
  }

  mobileLinks.forEach(link => link.addEventListener('click', closeMenu));

  document.addEventListener('keydown', e => {
    if (e.key === 'Escape') closeMenu();
  });

  // Закрытие бургера при клике вне header,
  // но НЕ если клик был внутри .locale-selector
  document.addEventListener('click', (e) => {
    if (
      header?.classList.contains('is-open') &&
      !header.contains(e.target) &&
      !e.target.closest('.locale-selector')  // ← исключаем селектор
    ) {
      closeMenu();
    }
  });
});

document.addEventListener('DOMContentLoaded', function () {
  const locale = window.__swLocale && window.__swLocale.getUrlLocale
    ? window.__swLocale.getUrlLocale()
    : new URLSearchParams(window.location.search).get('locale');

  const currentPath = window.location.pathname;
  const isHomePage = currentPath.endsWith('index.html') || currentPath.endsWith('/');

  const homePath = isHomePage
    ? currentPath
    : currentPath.substring(0, currentPath.lastIndexOf('/') + 1) + 'index.html';

  document.querySelectorAll('a[href]').forEach(function (a) {
    const href = a.getAttribute('href');
    if (!href || href.startsWith('mailto:') || href.startsWith('http')) return;

    if (href.startsWith('#')) {
      const base = isHomePage ? currentPath : homePath;
      const url = new URL(base, window.location.href);
      if (locale) url.searchParams.set('locale', locale);
      url.hash = href;
      a.setAttribute('href', url.pathname + url.search + url.hash);
      return;
    }

    if (locale) {
      const url = new URL(href, window.location.href);
      url.searchParams.set('locale', locale);
      a.setAttribute('href', url.pathname + url.search + url.hash);
    }
  });
});

document.addEventListener("DOMContentLoaded", function () {
  var trigger = document.getElementById("mobileIndTrigger");
  var overlay = document.getElementById("mobIndOverlay");
  var views = document.getElementById("mobIndViews");
  var detailScroll = document.getElementById("mobIndDetailScroll");
  var detailTitle = document.getElementById("mobIndDetailTitle");
  var backBtn = document.getElementById("mobIndBack");

  if (!trigger || !overlay) return;

  function openModal() {
    overlay.classList.add("is-open");
    overlay.removeAttribute("aria-hidden");
    document.body.style.overflow = "hidden";
  }

  function closeModal() {
    overlay.classList.remove("is-open");
    overlay.setAttribute("aria-hidden", "true");
    document.body.style.overflow = "";
    setTimeout(function () {
      if (views) views.classList.remove("detail-open");
      if (detailScroll) detailScroll.innerHTML = "";
      if (detailTitle) detailTitle.textContent = "";
    }, 350);
  }

  function openDetail(indKey) {
    var panel = document.querySelector('[data-panel="' + indKey + '"]');
    if (!panel) return;

    var labelEl = panel.querySelector(".ind-industry-label");
    var titleEl = panel.querySelector(".ind-industry-title");
    var bodyEl = panel.querySelector(".ind-industry-body");
    var ctaEl = panel.querySelector(".ind-cta-link");
    var subItems = panel.querySelectorAll(".ind-sub-item");

    if (detailTitle) {
      detailTitle.textContent = titleEl ? titleEl.textContent : "";
    }

    var html = "";

    html += '<div class="mob-ind-detail-head">';
    if (labelEl) html += '<p class="mob-ind-detail-label">' + labelEl.innerHTML + "</p>";
    if (titleEl) html += '<h3 class="mob-ind-detail-title">' + titleEl.innerHTML + "</h3>";
    if (bodyEl) html += '<p class="mob-ind-detail-body">' + bodyEl.innerHTML + "</p>";
    if (ctaEl) {
      html +=
        '<a href="' +
        (ctaEl.getAttribute("href") || "#") +
        '" class="mob-ind-detail-cta">' +
        ctaEl.innerHTML +
        "</a>";
    }
    html += "</div>";

    html += '<ul class="mob-ind-sublist">';
    subItems.forEach(function (item) {
      var isDisabled = !!item.querySelector(".ind-badge");
      var iconEl = item.querySelector(".ind-sub-icon");
      var textSpan = item.querySelector(
        "span:not(.ind-sub-icon):not(.ind-badge):not(.ind-sub-arrow)",
      );
      var href = item.getAttribute("href") || "#";

      if (isDisabled) {
        html += '<span class="mob-ind-subitem is-disabled">';
      } else {
        html += '<a href="' + href + '" class="mob-ind-subitem">';
      }

      if (iconEl) {
        html += '<span class="mob-ind-subicon">' + iconEl.innerHTML + "</span>";
      }
      if (textSpan) {
        html += "<span>" + textSpan.innerHTML + "</span>";
      }

      html += isDisabled ? "</span>" : "</a>";
    });
    html += "</ul>";

    if (detailScroll) {
      detailScroll.innerHTML = html;
      detailScroll.scrollTop = 0;
    }

    if (views) views.classList.add("detail-open");
  }

  trigger.addEventListener("click", openModal);

  if (backBtn) {
    backBtn.addEventListener("click", function () {
      if (views) views.classList.remove("detail-open");
    });
  }

  document.querySelectorAll(".mob-ind-close-btn").forEach(function (btn) {
    btn.addEventListener("click", closeModal);
  });

  overlay.addEventListener("click", function (e) {
    if (e.target === overlay) closeModal();
  });

  document.querySelectorAll(".mob-ind-navitem:not(.is-disabled)").forEach(function (item) {
    item.addEventListener("click", function () {
      openDetail(this.dataset.ind);
    });
  });

  document.addEventListener("keydown", function (e) {
    if (e.key === "Escape" && overlay.classList.contains("is-open")) {
      closeModal();
    }
  });
});

document.addEventListener(
  "mouseenter",
  function (e) {
    if (!e.target || typeof e.target.closest !== "function") return;
    const menuItem = e.target.closest(".header-menu-item");
    if (!menuItem || menuItem.dataset.bgLoaded) return;
    menuItem.dataset.bgLoaded = "true";
    menuItem.style.setProperty(
      "--menu-item-bg",
      'url("/core/image/${SECTION_01_HEADER_CORPORATE_REFERENCE_MENU_ITEM_SHADOW@IMAGE}/get")',
    );
  },
  true,
);

document.addEventListener("DOMContentLoaded", function () {
  const wrappers = document.querySelectorAll(".resources-dropdown-wrapper");

  wrappers.forEach((wrapper) => {
    const trigger = wrapper.querySelector(".resources-trigger");
    if (!trigger) return;

    let timer;

    const openMenu = () => {
      clearTimeout(timer);
      timer = setTimeout(() => {
        wrappers.forEach((el) => {
          if (el !== wrapper) {
            el.classList.remove("is-open");
            el.querySelector(".resources-trigger")?.setAttribute("aria-expanded", "false");
          }
        });
        wrapper.classList.add("is-open");
        trigger.setAttribute("aria-expanded", "true");
      }, 80);
    };

    const closeMenu = () => {
      clearTimeout(timer);
      timer = setTimeout(() => {
        wrapper.classList.remove("is-open");
        trigger.setAttribute("aria-expanded", "false");
      }, 200);
    };

    wrapper.addEventListener("mouseenter", openMenu);
    wrapper.addEventListener("mouseleave", closeMenu);

    trigger.addEventListener("click", (e) => {
      e.preventDefault();
      e.stopPropagation();
      const isOpen = wrapper.classList.contains("is-open");
      clearTimeout(timer);
      if (isOpen) {
        wrapper.classList.remove("is-open");
        trigger.setAttribute("aria-expanded", "false");
      } else {
        wrappers.forEach((el) => {
          if (el !== wrapper) {
            el.classList.remove("is-open");
            el.querySelector(".resources-trigger")?.setAttribute("aria-expanded", "false");
          }
        });
        wrapper.classList.add("is-open");
        trigger.setAttribute("aria-expanded", "true");
      }
    });
  });

  document.addEventListener("click", (e) => {
    if (!e.target.closest(".resources-dropdown-wrapper") && !e.target.closest(".locale-selector")) {
      wrappers.forEach((wrapper) => {
        wrapper.classList.remove("is-open");
        wrapper.querySelector(".resources-trigger")?.setAttribute("aria-expanded", "false");
      });
    }
  });

  // Industries panel hover logic
  const indWrapper = document.querySelector('[data-dropdown="industries"]');
  if (!indWrapper) return;

  const navItems = indWrapper.querySelectorAll(".ind-nav-item");
  const panels = indWrapper.querySelectorAll(".ind-panel");
  const defaultPanel = indWrapper.querySelector('[data-panel="default"]');

  let panelTimer;

  const showPanel = (targetKey) => {
    clearTimeout(panelTimer);
    panels.forEach((p) => p.classList.remove("is-active"));
    navItems.forEach((i) => i.classList.remove("is-active"));

    const panel = indWrapper.querySelector('[data-panel="' + targetKey + '"]');
    const item = indWrapper.querySelector('[data-ind="' + targetKey + '"]');
    if (panel) panel.classList.add("is-active");
    if (item) item.classList.add("is-active");
  };

  const showDefault = () => {
    panelTimer = setTimeout(() => {
      panels.forEach((p) => p.classList.remove("is-active"));
      navItems.forEach((i) => i.classList.remove("is-active"));
      if (defaultPanel) defaultPanel.classList.add("is-active");
    }, 100);
  };

  navItems.forEach((item) => {
    item.addEventListener("mouseenter", () => {
      showPanel(item.dataset.ind);
    });
  });

  const indRight = indWrapper.querySelector(".ind-right");
  const indLeft = indWrapper.querySelector(".ind-left");

  if (indLeft) {
    indLeft.addEventListener("mouseleave", showDefault);
  }

  if (indRight) {
    indRight.addEventListener("mouseenter", () => clearTimeout(panelTimer));
  }
});

document.addEventListener('DOMContentLoaded', function () {
  'use strict';

  if (window.__localeSelectorInit) return;
  window.__localeSelectorInit = true;

  const LOCALE_TO_COUNTRY = {
    'en': 'us', 'zh': 'cn', 'ar': 'sa', 'ko': 'kr', 'ja': 'jp',
    'uk': 'ua', 'cs': 'cz', 'el': 'gr', 'da': 'dk', 'sv': 'se',
    'fi': 'fi', 'nb': 'no', 'vi': 'vn', 'fa': 'ir', 'he': 'il',
    'hi': 'in', 'ms': 'my', 'th': 'th', 'id': 'id', 'et': 'ee',
    'lv': 'lv', 'lt': 'lt', 'sl': 'si', 'sk': 'sk',
  };

  function getLocaleFromURL() {
    return window.__swLocale && window.__swLocale.getUrlLocale
      ? window.__swLocale.getUrlLocale()
      : new URLSearchParams(window.location.search).get('locale');
  }

  function getLocaleFromDocument() {
    const normalizeLocale = window.__swLocale && window.__swLocale.normalizeLocale
      ? window.__swLocale.normalizeLocale
      : value => (value || '').toString().toLowerCase().split('-')[0];
    return normalizeLocale(document.documentElement.getAttribute('lang'));
  }

  function setLocaleInURL(value) {
    const locale = window.__swLocale && window.__swLocale.normalizeLocale
      ? window.__swLocale.normalizeLocale(value)
      : value;
    const url = new URL(window.location.href);
    const pathParts = url.pathname.split('/');
    const pathLocale = window.__swLocale && window.__swLocale.getPathLocale
      ? window.__swLocale.getPathLocale()
      : '';
    if (pathLocale) {
      pathParts[1] = locale;
      url.pathname = pathParts.join('/') || '/';
      url.searchParams.delete('locale');
    } else {
      url.searchParams.set('locale', locale);
    }
    window.location.assign(url.toString());
  }

  function detectBrowserLocale(availableLanguages) {
    const normalizeLocale = window.__swLocale && window.__swLocale.normalizeLocale
      ? window.__swLocale.normalizeLocale
      : value => (value || '').toString().toLowerCase().split('-')[0];
    const browserLangs = navigator.languages?.length
      ? navigator.languages
      : [navigator.language || navigator.userLanguage || 'en'];

    for (const browserLang of browserLangs) {
      const code = normalizeLocale(browserLang);
      const match = availableLanguages.find(l => l.code2 === code);
      if (match) return match.code2;
    }
    return 'en';
  }

  function resolveCurrentLocale(availableLanguages) {
    const normalizeLocale = window.__swLocale && window.__swLocale.normalizeLocale
      ? window.__swLocale.normalizeLocale
      : value => (value || '').toString().toLowerCase().split('-')[0];
    const candidates = [
      getLocaleFromURL(),
      getLocaleFromDocument(),
      window.__swLocale && window.__swLocale.getEffectiveLocale
        ? window.__swLocale.getEffectiveLocale()
        : '',
      detectBrowserLocale(availableLanguages),
    ];

    for (const candidate of candidates) {
      const code = normalizeLocale(candidate);
      const match = availableLanguages.find(l => l.code2 === code);
      if (match) return match.code2;
    }

    return 'en';
  }

  function createFlagElement(code2) {
    const countryCode = (LOCALE_TO_COUNTRY[code2] || code2).toLowerCase();
    const span = document.createElement('span');
    span.classList.add('flag-icon', 'flag-icon-' + countryCode, 'locale-flag');
    span.setAttribute('aria-hidden', 'true');
    return span;
  }

  function createCheckIcon() {
    const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
    svg.setAttribute('class', 'locale-check');
    svg.setAttribute('viewBox', '0 0 14 14');
    svg.setAttribute('fill', 'none');
    svg.innerHTML = '<path d="M2.5 7L5.5 10L11.5 4" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"/>';
    return svg;
  }

  function initSelector(selector) {
    const trigger      = selector.querySelector('.locale-trigger');
    const dropdown     = selector.querySelector('.locale-dropdown');
    const triggerLabel = selector.querySelector('.locale-trigger-label');

    if (!trigger || !dropdown) return;

    function open() {
      document.querySelectorAll('.locale-selector.is-open').forEach(el => {
        if (el !== selector) {
          el.classList.remove('is-open');
          el.querySelector('.locale-trigger')?.setAttribute('aria-expanded', 'false');
        }
      });
      selector.classList.add('is-open');
      trigger.setAttribute('aria-expanded', 'true');
    }

    function close() {
      selector.classList.remove('is-open');
      trigger.setAttribute('aria-expanded', 'false');
    }

    function toggle() {
      selector.classList.contains('is-open') ? close() : open();
    }

    // ↓ НОВОЕ: останавливаем всплытие со всего селектора
    selector.addEventListener('click', (e) => {
      e.stopPropagation();
    });

    trigger.addEventListener('click', (e) => {
      e.stopPropagation();
      toggle();
    });

    function bindArrowNav() {
      dropdown.addEventListener('keydown', (e) => {
        const items   = Array.from(dropdown.querySelectorAll('.locale-item'));
        const focused = document.activeElement;
        const idx     = items.indexOf(focused);

        if (e.key === 'ArrowDown') {
          e.preventDefault();
          (items[idx + 1] || items[0]).focus();
        } else if (e.key === 'ArrowUp') {
          e.preventDefault();
          (items[idx - 1] || items[items.length - 1]).focus();
        }
      });
    }

    function renderItems(languages, currentLocale) {
      const list = dropdown.querySelector('.locale-list');
      if (!list) return;

      list.innerHTML = '';

      languages.forEach(lang => {
        const code  = lang.code2;
        const label = lang.nativeName || code;

        const li = document.createElement('li');
        li.className     = 'locale-item' + (code === currentLocale ? ' is-active' : '');
        li.role          = 'option';
        li.tabIndex      = 0;
        li.dataset.value = code;
        li.dataset.label = label;
        li.setAttribute('aria-selected', code === currentLocale ? 'true' : 'false');

        const span = document.createElement('span');
        span.className   = 'locale-item-label';
        span.textContent = label;

        li.appendChild(createFlagElement(code));
        li.appendChild(span);
        li.appendChild(createCheckIcon());

        li.addEventListener('click', (e) => {
          e.stopPropagation();
          setLocaleInURL(code);
        });

        li.addEventListener('keydown', (e) => {
          if (e.key === 'Enter' || e.key === ' ') {
            e.preventDefault();
            setLocaleInURL(code);
          }
        });

        list.appendChild(li);
      });

      const active = languages.find(l => l.code2 === currentLocale);
      if (active && triggerLabel) {
        triggerLabel.textContent = active.nativeName || currentLocale;
        const existingFlag = trigger.querySelector('.locale-flag');
        const newFlag = createFlagElement(currentLocale);
        if (existingFlag) existingFlag.replaceWith(newFlag);
        else trigger.appendChild(newFlag);
      }
      bindArrowNav();
    }

    async function loadLanguages() {
      try {
        const res = await fetch('/core/api/language/active.json', {
          method: 'POST',
          headers: { 'accept': 'application/json', 'Content-Type': 'application/json' },
          body: JSON.stringify([{ name: 'code2' }, { name: 'nativeName' }])
        });
        if (!res.ok) throw new Error('HTTP ' + res.status);
        const languages = await res.json();
        const currentLocale = resolveCurrentLocale(languages);
        renderItems(languages, currentLocale);
      } catch (err) {
        console.error('[LocaleSelector] Failed:', err);
      }
    }

    document.addEventListener('click', (e) => {
      if (!selector.contains(e.target)) {
        close();
      }
    });

    document.addEventListener('keydown', (e) => {
      if (e.key === 'Escape' && selector.classList.contains('is-open')) {
        close();
        trigger.focus();
      }
    });

    loadLanguages();
  }

  document.querySelectorAll('.locale-selector').forEach(initSelector);
});

children.css:
/* generated child CSS: 14-pricing/pricing.plans-flex/block.css */
/* lab-ui block · pricing.plans-flex
   Depends: 00-tokens/tokens.css. Light theme.
   Visual identity differs from pricing.plan-cards:
     · flat card surface (no internal white-on-gray gradient),
     · featured plan uses a 2px cta-accent ring + lifted shadow,
     · monospace price digits keep the ledger/operations feel,
     · sliding indicator inside the billing toggle,
     · per-card Save chip that fade-scales in for Annual,
     · price + billed-caption crossfade between billing modes,
     · static fallback slots controlled per slot via data-plan-visible.
     Dynamic mode can render any returned plan count. */

.pf-plans {
  background: var(--color-bg);
  color: var(--color-text);
  font-family: var(--font-family);
  overflow-x: clip;
}
.pf-plans .container {
  max-width: calc(var(--container-width) + var(--container-padding-x) * 2);
  margin-inline: auto;
  padding-inline: var(--container-padding-x);
}

/* ─── Header ────────────────────────────────────────────────── */
.pf-top {
  max-width: 58rem;
  margin-inline: auto;
  text-align: center;
  margin-bottom: 44px;
}
.pf-eyebrow {
  margin: 0 0 14px;
  font-family: var(--font-mono);
  font-size: var(--type-eyebrow-size);
  letter-spacing: var(--type-eyebrow-tracking);
  text-transform: uppercase;
  color: var(--color-text-accent);
}
.pf-title {
  margin: 0;
  color: var(--color-heading);
  font-size: var(--type-h1-size);
  font-weight: var(--type-h1-weight);
  line-height: var(--type-h1-leading);
  letter-spacing: var(--type-h1-tracking);
  overflow-wrap: break-word;
}
.pf-lede {
  max-width: 45rem;
  margin: 18px auto 0;
  font-size: 1.0625rem;
  line-height: 1.55;
}

/* ─── Toggle · sliding pill indicator ───────────────────────── */
.pf-toggle {
  position: relative;
  display: inline-grid;
  grid-template-columns: minmax(120px, 1fr) minmax(120px, 1fr);
  margin-top: 28px;
  padding: 4px;
  border: 1px solid rgba(146, 170, 205, 0.30);
  border-radius: var(--radius-pill);
  background: var(--color-gray-bg);
  isolation: isolate;
}
.pf-toggle::before {
  content: "";
  position: absolute;
  z-index: 0;
  top: 4px;
  bottom: 4px;
  left: 4px;
  width: calc(50% - 4px);
  border-radius: var(--radius-pill);
  background: var(--color-white);
  box-shadow: var(--shadow-1);
  transition: transform 0.34s cubic-bezier(0.32, 0.72, 0, 1);
}
.pf-plans[data-billing="annual"] .pf-toggle::before {
  transform: translateX(100%);
}
.pf-toggle-opt {
  position: relative;
  z-index: 1;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 44px;
  padding: 0 18px;
  border: 0;
  border-radius: var(--radius-pill);
  background: transparent;
  color: var(--color-text);
  font-size: 0.9375rem;
  font-weight: 600;
  cursor: pointer;
  transition: color 0.24s ease;
}
.pf-toggle-opt.is-active {
  color: var(--color-heading);
}

.pf-note {
  margin: 14px 0 0;
  color: var(--color-gray-blue);
  font-size: 0.8125rem;
  line-height: 1.45;
}

/* ─── Grid · flexible static fallback slots ───────────────────
   Parent grid defines 8 explicit row tracks that match a card's
   8 logical sections (head, name, subtitle, price, billed, cta,
   features, disclaimer). Cards opt-in via grid-template-rows: subgrid
   so every card's track-N is sized to the tallest card's track-N —
   head row, subtitle row, price row, CTA row all align horizontally
   regardless of how long any one card's text is. The final track is
   1fr so each card stretches to fill the row-band's max height; the
   disclaimer self-aligns to the bottom of that flexible track.
   Dynamic mode disables the static subgrid tracks so any plan count can
   wrap naturally. */
.pf-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  /* Two explicit 8-track bands: when the grid wraps to two columns
     (tablet), the second card band still ends in a flexible track so
     its disclaimers bottom-align the same way as the first band. */
  grid-template-rows: repeat(7, auto) 1fr repeat(7, auto) 1fr;
  column-gap: 20px;
  /* Separates card bands when the grid wraps; inside a card the
     subgrid's own row-gap: 0 absorbs these gutters, so internal
     spacing is unaffected. */
  row-gap: 20px;
  max-width: 100%;
}
.pf-card[data-plan-visible="hide"] { display: none; }
.pf-card--skeleton {
  display: none;
  pointer-events: none;
}

.pf-plans[data-pricing-dynamic="true"]:not([data-pricing-state="dynamic"]):not([data-pricing-state="fallback"]) .pf-card--skeleton {
  display: grid;
}

.pf-plans[data-pricing-dynamic="true"]:not([data-pricing-state="dynamic"]):not([data-pricing-state="fallback"]) [data-plan-slot] {
  display: none;
}

.pf-skel {
  display: block;
  border-radius: var(--radius-pill);
  background: linear-gradient(90deg, rgba(146, 170, 205, 0.14), rgba(146, 170, 205, 0.28), rgba(146, 170, 205, 0.14));
  background-size: 200% 100%;
  animation: pf-skeleton 1.2s ease-in-out infinite;
}
.pf-skel--kicker { width: 38%; height: 22px; }
.pf-skel--title { width: 64%; height: 30px; margin-top: 18px; }
.pf-skel--text { width: 100%; height: 52px; margin-top: 12px; border-radius: 12px; }
.pf-skel--price { width: 54%; height: 42px; margin-top: 24px; }
.pf-skel--button { width: 100%; height: 46px; margin-top: 18px; }
.pf-skel--line { width: 92%; height: 14px; margin-top: 18px; }
.pf-skel--short { width: 68%; margin-top: 10px; }

@keyframes pf-skeleton {
  to { background-position-x: -200%; }
}

.pf-plans[data-pricing-state="dynamic"] .pf-grid {
  grid-template-rows: none;
  align-items: stretch;
}

.pf-plans[data-pricing-state="dynamic"] .pf-card {
  display: grid;
  grid-template-rows:
    minmax(26px, auto)
    auto
    minmax(4.35rem, auto)
    minmax(4.75rem, auto)
    minmax(4.125rem, auto)
    1fr
    auto;
  grid-row: auto;
}

.pf-plans[data-pricing-state="dynamic"] .pf-billed-stack {
  display: none;
}

.pf-plans[data-pricing-state="dynamic"] .pf-features {
  align-content: start;
}

.pf-plans[data-pricing-state="dynamic"] .pf-disclaimer {
  margin-top: auto;
}

.pf-plans[data-pricing-state="dynamic"] .pf-disclaimer:empty {
  display: none;
}

/* ─── Plan card · flat surface ──────────────────────────────── */
.pf-card {
  position: relative;
  display: grid;
  grid-template-rows: subgrid;
  grid-template-columns: minmax(0, 1fr);
  grid-row: span 8;
  row-gap: 0;
  min-width: 0;
  padding: 24px;
  border: 1px solid rgba(146, 170, 205, 0.28);
  border-radius: var(--radius-card);
  background: var(--color-white);
  transition: transform var(--transition-fast), box-shadow var(--transition-fast);
}
.pf-card--muted {
  background: var(--color-gray-bg);
}
.pf-card--featured {
  border-color: var(--cta-accent);
  box-shadow: 0 0 0 1px var(--cta-accent), 0 22px 48px -30px rgba(27, 29, 37, 0.32);
  transform: translateY(-4px);
}
@media (hover: hover) {
  .pf-card:hover {
    transform: translateY(-2px);
    box-shadow: var(--shadow-2);
  }
  .pf-card--featured:hover {
    transform: translateY(-6px);
  }
}

.pf-card-head {
  display: flex;
  min-height: 26px;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}
.pf-card-head:has(.pf-kicker:empty):has(.pf-badge:empty) {
  display: none;
}
.pf-kicker,
.pf-badge {
  display: inline-flex;
  max-width: 100%;
  align-items: center;
  min-height: 22px;
  border-radius: var(--radius-pill);
  font-family: var(--font-mono);
  font-size: 0.6875rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  white-space: nowrap;
}
.pf-kicker { color: var(--color-gray-blue); }
.pf-kicker:empty,
.pf-badge:empty {
  display: none;
}
.pf-badge {
  padding: 3px 9px;
  color: var(--color-heading);
  background: var(--cta-accent-soft);
}
.pf-card--featured .pf-badge { background: var(--cta-accent); }

.pf-name {
  margin: 18px 0 0;
  color: var(--color-heading);
  font-size: 1.5rem;
  font-weight: 650;
  line-height: 1.15;
  letter-spacing: -0.01em;
}
.pf-subtitle {
  min-height: 52px;
  margin: 8px 0 0;
  font-size: 0.9375rem;
  line-height: 1.45;
}

/* ─── Price block · crossfade between monthly/annual ────────── */
.pf-price {
  display: flex;
  align-items: baseline;
  gap: 8px;
  flex-wrap: wrap;
  margin-top: 22px;
  color: var(--color-heading);
}
.pf-currency {
  font-size: 1rem;
  font-weight: 600;
}
.pf-amount-stack {
  display: inline-grid;
  align-items: baseline;
}
.pf-amount {
  grid-column: 1;
  grid-row: 1;
  font-family: var(--font-mono);
  font-size: 2.5rem;
  font-weight: 600;
  line-height: 1;
  letter-spacing: -0.02em;
  transition:
    opacity 0.24s ease-out,
    transform 0.34s cubic-bezier(0.16, 1, 0.3, 1);
  will-change: opacity, transform;
}
.pf-period {
  color: var(--color-gray-blue);
  font-size: 0.875rem;
}

/* Per-card Save chip · appears in Annual mode */
.pf-card-save {
  display: inline-flex;
  align-items: center;
  padding: 3px 9px;
  border-radius: var(--radius-pill);
  background: var(--cta-accent-soft);
  color: var(--color-heading);
  font-family: var(--font-mono);
  font-size: 0.6875rem;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  transform-origin: left center;
  opacity: 0;
  transform: scale(0.78) translateY(2px);
  transition:
    opacity 0.22s ease-out,
    transform 0.22s ease-out;
  transition-delay: 0s;
}
.pf-card-save:empty { display: none; }
.pf-plans[data-billing="annual"] .pf-card-save {
  opacity: 1;
  transform: scale(1) translateY(0);
  transition:
    opacity 0.32s cubic-bezier(0.16, 1, 0.3, 1),
    transform 0.34s cubic-bezier(0.16, 1, 0.3, 1);
  transition-delay: 0.34s;
}

/* Billed caption crossfade · stacks monthly/annual in same cell */
.pf-billed-stack {
  display: grid;
  margin-top: 6px;
  min-height: 16px;
}
.pf-billed {
  grid-column: 1;
  grid-row: 1;
  color: var(--color-gray-blue);
  font-size: 0.75rem;
  letter-spacing: 0.02em;
  transition:
    opacity 0.22s ease-out,
    transform 0.30s cubic-bezier(0.16, 1, 0.3, 1);
}

/* Crossfade rules · outgoing leaves immediately, incoming arrives with a delay
   so the swap reads as motion instead of an instant flip. */
.pf-plans[data-billing="monthly"] [data-price-annual],
.pf-plans[data-billing="monthly"] [data-billed-annual] {
  opacity: 0;
  transform: translateY(-14px);
  pointer-events: none;
}
.pf-plans[data-billing="annual"] [data-price-monthly],
.pf-plans[data-billing="annual"] [data-billed-monthly] {
  opacity: 0;
  transform: translateY(14px);
  pointer-events: none;
}
.pf-plans[data-billing="monthly"] [data-price-monthly],
.pf-plans[data-billing="monthly"] [data-billed-monthly],
.pf-plans[data-billing="annual"]  [data-price-annual],
.pf-plans[data-billing="annual"]  [data-billed-annual] {
  transition:
    opacity 0.30s cubic-bezier(0.16, 1, 0.3, 1),
    transform 0.40s cubic-bezier(0.16, 1, 0.3, 1);
  transition-delay: 0.18s;
}

/* ─── CTA · 3 styles, matches token vocabulary ──────────────── */
.pf-cta {
  display: inline-flex;
  justify-content: center;
  align-items: center;
  min-height: 44px;
  margin-top: 22px;
  padding: 0 18px;
  border-radius: var(--radius-pill);
  font-weight: 650;
  font-size: 0.9375rem;
  text-decoration: none;
  transition: transform var(--transition-fast), box-shadow var(--transition-fast);
}
.pf-cta:hover {
  transform: translateY(-1px);
  box-shadow: var(--shadow-glow-soft);
}
.pf-cta[aria-disabled="true"] {
  cursor: not-allowed;
  color: var(--color-gray-blue);
  background: var(--color-gray-bg);
  border: 1px solid rgba(146, 170, 205, 0.28);
  box-shadow: none;
  opacity: 0.72;
}
.pf-cta[aria-disabled="true"]:hover {
  transform: none;
  box-shadow: none;
}
.pf-cta--primary {
  color: var(--button-primary-color);
  background:
    linear-gradient(var(--color-white), var(--color-white)) padding-box,
    var(--gradient-cta-ring) border-box;
  border: 1px solid transparent;
}
.pf-cta--filled {
  color: var(--cta-secondary-color, var(--color-white));
  background: var(--cta-secondary-fill);
  border: 1px solid var(--cta-secondary-border, rgba(255, 255, 255, 0.18));
}
.pf-cta--ghost {
  color: var(--color-heading);
  background: var(--color-white);
  border: 1px solid rgba(146, 170, 205, 0.35);
}

/* ─── Features list ─────────────────────────────────────────── */
.pf-features {
  display: grid;
  gap: 10px;
  margin: 22px 0 0;
  padding: 0;
  list-style: none;
}
.pf-features:empty { display: none; }
.pf-features li {
  position: relative;
  padding-left: 22px;
  font-size: 0.875rem;
  line-height: 1.45;
}
.pf-features li:empty { display: none; }
.pf-features li::before {
  content: "";
  position: absolute;
  left: 0;
  top: 0.5em;
  width: 8px;
  height: 8px;
  border-radius: 999px;
  background: var(--cta-accent);
  box-shadow: 0 0 0 3px var(--cta-accent-soft);
}
.pf-disclaimer {
  align-self: end;
  margin: 0;
  padding-top: 22px;
  color: var(--color-gray-blue);
  font-size: 0.75rem;
  line-height: 1.45;
}
.pf-disclaimer:empty { visibility: hidden; }

/* ─── Responsive ────────────────────────────────────────────── */
@media (max-width: 1100px) {
  .pf-grid {
    grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
  }
  /* In the wrapped 2-column zone the -4px lift makes the featured card
     visibly misalign with its band neighbor; keep the ring, drop the lift. */
  .pf-card--featured { transform: none; }
}
@media (max-width: 720px) {
  .pf-plans .container {
    max-width: 100%;
    padding-inline: 20px;
  }
  .pf-top { text-align: left; }
  .pf-title { font-size: 2.125rem; line-height: 1.08; }
  .pf-lede { margin-inline: 0; }
  .pf-toggle { width: 100%; grid-template-columns: 1fr 1fr; }
  .pf-grid { grid-template-columns: 1fr; gap: 14px; }
  .pf-card--featured {
    transform: none;
    /* Featured plan first in the single-column stack: the recommended
       tier should not hide below the fold behind the entry plan. */
    order: -1;
  }
  .pf-subtitle { min-height: 0; }
}

/* ─── Accessibility ─────────────────────────────────────────── */
.pf-toggle-opt:focus-visible,
.pf-cta:focus-visible {
  outline: 2px solid var(--cta-accent);
  outline-offset: 2px;
}
@media (prefers-reduced-motion: reduce) {
  .pf-plans *,
  .pf-plans *::before,
  .pf-plans *::after {
    transition-duration: 0.01ms !important;
